"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


REQUIRED = {
    "routines": ("name", "every", "last_time", "last_code"),
    "schedule": ("name", "at", "claimed"),
}
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def reject_constant(value):
    raise ValueError("non-finite JSON constant")


def read_table(node, name, bad):
    try:
        with (node / "wf" / (name + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        data = None
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(col, str) for col in data["columns"])
            or not isinstance(data.get("rows"), list)):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    return data["rows"]


def parse_time(text, now):
    stamp = datetime.fromisoformat(text)
    return stamp.replace(tzinfo=now.tzinfo) if stamp.tzinfo is None else stamp


def routine(row, now):
    every = row["every"]
    if re.fullmatch(r"[1-9][0-9]*[rsmhd]", every) is None:
        raise ValueError("invalid every")
    last = parse_time(row["last_time"], now) if row["last_time"] else None
    code = row["last_code"]
    if code == "":
        code = None
    elif code != "running":
        if re.fullmatch(r"[+-]?[0-9]+", code) is None:
            raise ValueError("invalid last_code")
        code = int(code)
    next_time = None
    if last is not None and every[-1] != "r":
        next_time = last + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_time is not None and now >= next_time:
        state = "overdue"
    else:
        state = "ok"
    rendered = (next_time.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                if next_time is not None else None)
    return {"name": row["name"], "every": every,
            "last_time": row["last_time"] if last is not None else None,
            "last_code": code, "state": state, "next": rendered}


def scheduled(row, now):
    at = parse_time(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(
                  ("running", "never", "failed", "overdue", "ok"), 0),
                  "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": bad}
    for table in ("routines", "schedule"):
        seen = set()
        for index, row in enumerate(read_table(node, table, bad)):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name and name in seen:
                bad.append({"table": table, "row": index, "why": "dup_name"})
                continue
            if isinstance(name, str) and name:
                seen.add(name)
            if (not isinstance(row, dict) or not isinstance(name, str) or not name
                    or not all(isinstance(value, str) for value in row.values())
                    or not all(key in row for key in REQUIRED[table])):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            try:
                item = routine(row, now) if table == "routines" else scheduled(row, now)
            except (ValueError, OverflowError):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            result[table].append(item)
            result["counts"][table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    bad.sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow table summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), separators=(",", ":"), allow_nan=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
